<!DOCTYPE html>
<html>
<head>
  <title>Carnival Map</title>
  <style>
    #map-container {
      position: relative;
      width: 1000px;
      height: 800px;
    }
    #map-img {
      width: 100%;
      height: 100%;
    }
    #overlay {
      position: absolute;
      left: 0;
      top: 0;
    }
  </style>
</head>
<body>
  <h2>Carnival Travel Route</h2>
  <div id="map-container">
    <img id="map-img" src="map_base.png" alt="Map">
    <canvas id="overlay" width="1000" height="800"></canvas>
  </div>

  <script>
    // Simple linear mapping from lat/lon to canvas x/y
    function latlonToXY(lat, lon) {
      const bounds = {
        latMin: 25.5, latMax: 42.5,
        lonMin: -109.1, lonMax: -93.5
      };
      const width = 1000, height = 800;
      const x = ((lon - bounds.lonMin) / (bounds.lonMax - bounds.lonMin)) * width;
      const y = ((bounds.latMax - lat) / (bounds.latMax - bounds.latMin)) * height;
      return [x, y];
    }

    const ctx = document.getElementById("overlay").getContext("2d");

    // Locations (simplified)
    const points = [
      { name: "College Station", lat: 30.6279, lon: -96.3344 },
      { name: "San Angelo", lat: 31.4638, lon: -100.4370 },
      { name: "Midland", lat: 31.9973, lon: -102.0779 }
    ];

    // Draw stars
    ctx.fillStyle = "green";
    points.forEach(p => {
      const [x, y] = latlonToXY(p.lat, p.lon);
      ctx.beginPath();
      ctx.arc(x, y, 6, 0, 2 * Math.PI);
      ctx.fill();
    });

    // Draw travel vectors
    ctx.strokeStyle = "blue";
    ctx.lineWidth = 2;
    for (let i = 0; i < points.length - 1; i++) {
      const [x1, y1] = latlonToXY(points[i].lat, points[i].lon);
      const [x2, y2] = latlonToXY(points[i+1].lat, points[i+1].lon);
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();

      // Optional arrowhead
      const angle = Math.atan2(y2 - y1, x2 - x1);
      const arrowLength = 10;
      ctx.beginPath();
      ctx.moveTo(x2, y2);
      ctx.lineTo(x2 - arrowLength * Math.cos(angle - 0.3), y2 - arrowLength * Math.sin(angle - 0.3));
      ctx.lineTo(x2 - arrowLength * Math.cos(angle + 0.3), y2 - arrowLength * Math.sin(angle + 0.3));
      ctx.lineTo(x2, y2);
      ctx.fill();
    }
  </script>
</body>
</html>
```

