```javascript
function insertKeyword(text, cursorOffset) {
  const input = document.getElementById('searchInput');
  const originalText = input.value;
  const isActive = document.activeElement === input;
  let start, end;

  if (isActive && typeof input.selectionStart === "number") {
    start = input.selectionStart;
    end = input.selectionEnd;
  } else {
    // Insert at end
    start = end = originalText.length;
  }

  // Determine if space is needed before insertion
  const insertBefore = (start > 0 && originalText[start - 1] !== ' ') ? ' ' : '';
  const insertText = insertBefore + text;

  // Apply insertion
  input.value = originalText.slice(0, start) + insertText + originalText.slice(end);

  // Refocus and position cursor
  const cursorPos = start + insertText.length - text.length + cursorOffset;
  input.focus();
  input.setSelectionRange(cursorPos, cursorPos);
}
```

