      const input = document.getElementById('customSiteInput');
      const container = document.getElementById('siteControls');

      let value = dropdown.value;

      if (value === '__new') {
        let custom = input.value.trim();
        if (!custom) return;

        if (custom.endsWith('.')) {
          custom += 'com';
        } else if (!hasKnownSuffix(custom)) {
          custom += '.com';
        }

        value = custom;
        storeSite(value);
